import React, { useState, useEffect } from 'react';
import { 
  Box, 
  IconButton, 
  Menu, 
  MenuItem, 
  Typography, 
  useTheme 
} from '@mui/material';
import LanguageIcon from '@mui/icons-material/Language';
import CheckIcon from '@mui/icons-material/Check';

// Available languages
const languages = [
  { code: 'en', name: 'English' },
  { code: 'ar', name: 'العربية', direction: 'rtl' },
  { code: 'ur', name: 'اردو', direction: 'rtl' },
  { code: 'fr', name: 'Français' },
  { code: 'es', name: 'Español' },
  { code: 'id', name: 'Bahasa Indonesia' },
  { code: 'tr', name: 'Türkçe' },
  { code: 'ms', name: 'Bahasa Melayu' }
];

const LanguageSelector = ({ mobile = false }) => {
  const theme = useTheme();
  const [anchorEl, setAnchorEl] = useState(null);
  const [currentLanguage, setCurrentLanguage] = useState(() => {
    // Get saved language or use browser default
    const savedLang = localStorage.getItem('preferred-language');
    if (savedLang && languages.some(lang => lang.code === savedLang)) {
      return savedLang;
    }
    
    // Try to detect from browser
    const browserLang = navigator.language.split('-')[0];
    if (languages.some(lang => lang.code === browserLang)) {
      return browserLang;
    }
    
    // Default to English
    return 'en';
  });

  // Update document direction when language changes
  useEffect(() => {
    const selectedLang = languages.find(lang => lang.code === currentLanguage);
    if (selectedLang && selectedLang.direction === 'rtl') {
      document.documentElement.dir = 'rtl';
      document.documentElement.lang = currentLanguage;
    } else {
      document.documentElement.dir = 'ltr';
      document.documentElement.lang = currentLanguage;
    }
    // Save preference
    localStorage.setItem('preferred-language', currentLanguage);
  }, [currentLanguage]);

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLanguageSelect = (langCode) => {
    setCurrentLanguage(langCode);
    handleMenuClose();
    // In a real implementation, this would trigger language context update
    // i18n.changeLanguage(langCode);
  };

  const open = Boolean(anchorEl);

  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        ...(mobile
          ? {}
          : {
              position: 'fixed',
              bottom: '80px',
              right: '20px',
              zIndex: 1000,
              backgroundColor: theme.palette.background.paper,
              boxShadow: '0 3px 10px rgba(0,0,0,0.2)',
              p: 0.5,
              borderRadius: '50%',
            }),
      }}
    >
      <IconButton
        onClick={handleMenuOpen}
        color={mobile ? 'inherit' : 'primary'}
        aria-label="Select language"
        aria-controls="language-menu"
        aria-haspopup="true"
        aria-expanded={open ? 'true' : undefined}
      >
        <LanguageIcon />
      </IconButton>
      
      <Menu
        id="language-menu"
        anchorEl={anchorEl}
        open={open}
        onClose={handleMenuClose}
        MenuListProps={{
          'aria-labelledby': 'language-selector',
        }}
        transformOrigin={{ horizontal: 'right', vertical: 'top' }}
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
        PaperProps={{
          elevation: 3,
          sx: {
            maxHeight: 300,
            minWidth: 180,
          }
        }}
      >
        {languages.map((lang) => (
          <MenuItem 
            key={lang.code} 
            onClick={() => handleLanguageSelect(lang.code)}
            selected={currentLanguage === lang.code}
            sx={{ 
              justifyContent: 'space-between',
              direction: lang.direction || 'ltr'
            }}
          >
            <Typography variant="body2">{lang.name}</Typography>
            {currentLanguage === lang.code && (
              <CheckIcon fontSize="small" sx={{ ml: 1 }} />
            )}
          </MenuItem>
        ))}
      </Menu>
    </Box>
  );
};

export default LanguageSelector;