import React, { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { 
    Box, Container, AppBar, Toolbar, Typography, Button,
    Menu, MenuItem, IconButton, Drawer, List, ListItem, ListItemText, 
    Divider, useMediaQuery, useTheme, ListItemIcon
} from '@mui/material';
import { Link } from 'react-router-dom';
import MosqueIcon from '@mui/icons-material/Mosque';
import ApiIcon from '@mui/icons-material/Api';
import MenuIcon from '@mui/icons-material/Menu';
import ArrowDropDownIcon from '@mui/icons-material/ArrowDropDown';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import AccessTimeFilledIcon from '@mui/icons-material/AccessTimeFilled';
import SmartphoneIcon from '@mui/icons-material/Smartphone';
import MicIcon from '@mui/icons-material/Mic';
import MenuBookIcon from '@mui/icons-material/MenuBook';
import Footer from '../common/Footer';
import Logo from '../common/Logo';
import { motion } from 'framer-motion';

const Layout = ({ children }) => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    
    // For the Prayer Times dropdown menu
    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl);
    
    // For mobile drawer
    const [drawerOpen, setDrawerOpen] = useState(false);

    const handleMenuClick = (event) => {
        setAnchorEl(event.currentTarget);
    };
    
    const handleMenuClose = () => {
        setAnchorEl(null);
    };
    
    const handleDrawerToggle = () => {
        setDrawerOpen(!drawerOpen);
    };

    // Menu items
    const menuItems = [
        { 
            text: 'Prayer Times', 
            path: '/prayer-times',
            icon: <AccessTimeFilledIcon />,
            subItems: [
                { text: 'Calendar', path: '/calendar', icon: <CalendarTodayIcon /> },
                { text: 'Quran', path: '/quran', icon: <MenuBookIcon /> },
                { text: 'API', path: '/api', icon: <ApiIcon /> }
            ]
        },
        { text: 'Mobile App', path: '/mobile-app', icon: <SmartphoneIcon /> },
        { text: 'Alexa Skill', path: '/alexa-skill', icon: <MicIcon /> }
    ];

    // Mobile drawer navigation
    const mobileDrawer = (
        <Drawer
            anchor="right"
            open={drawerOpen}
            onClose={handleDrawerToggle}
        >
            <Box
                sx={{ width: 250 }}
                role="presentation"
                component="nav"
            >
                <List>
                    {/* Animated Quran menu item at the top */}
                    <ListItem 
                        button 
                        component={Link} 
                        to="/quran"
                        onClick={handleDrawerToggle}
                    >
                        <ListItemIcon>
                            <motion.div
                                animate={{
                                    rotate: [0, 360, 360, 0],
                                    scale: [1, 1.3, 1.1, 1.4, 1],
                                    boxShadow: [
                                        '0 0 0px #fff',
                                        '0 0 16px #ffd700',
                                        '0 0 32px #00e5ff',
                                        '0 0 24px #ffd700',
                                        '0 0 0px #fff'
                                    ],
                                    y: [0, -6, 0, 6, 0]
                                }}
                                transition={{
                                    duration: 2.5,
                                    repeat: Infinity,
                                    repeatType: 'loop',
                                    ease: 'easeInOut'
                                }}
                                style={{ display: 'inline-flex' }}
                            >
                                <MenuBookIcon sx={{ color: '#e4c04d', filter: 'drop-shadow(0 0 8px #e4c04d) drop-shadow(0 0 16px #e4c04d)' }} />
                            </motion.div>
                        </ListItemIcon>
                        <ListItemText primary="Quran" />
                    </ListItem>
                    <Divider />
                    {menuItems.map((item) => (
                        <React.Fragment key={item.text}>
                            <ListItem 
                                button 
                                component={Link} 
                                to={item.path}
                                onClick={handleDrawerToggle}
                            >
                                <ListItemIcon>
                                    {item.icon}
                                </ListItemIcon>
                                <ListItemText primary={item.text} />
                            </ListItem>
                            
                            {item.subItems && item.subItems.map((subItem) => (
                                <ListItem 
                                    button 
                                    component={Link} 
                                    to={subItem.path}
                                    onClick={handleDrawerToggle}
                                    sx={{ pl: 4 }}
                                    key={subItem.text}
                                >
                                    <ListItemIcon>
                                        {subItem.icon}
                                    </ListItemIcon>
                                    <ListItemText primary={subItem.text} />
                                </ListItem>
                            ))}
                        </React.Fragment>
                    ))}
                </List>
            </Box>
        </Drawer>
    );

    // Basic Schema.org JSON-LD
    const organizationSchema = {
        "@context": "https://schema.org",
        "@type": "Organization",
        "name": "iMuslim Life",
        "url": "https://imuslimlife.com",
        "logo": "https://imuslimlife.com/logo512.png",
        "sameAs": [
            // Add social media links here if available
            // "https://www.facebook.com/yourpage",
            // "https://twitter.com/yourhandle",
            "https://github.com/imuslimlife/"
        ]
    };

    const websiteSchema = {
        "@context": "https://schema.org",
        "@type": "WebSite",
        "name": "iMuslim Life",
        "url": "https://imuslimlife.com",
        "potentialAction": {
            "@type": "SearchAction",
            "target": "https://imuslimlife.com/#/search?q={search_term_string}", // Adjust if search functionality exists
            "query-input": "required name=search_term_string"
        }
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
            <Helmet>
                <title>iMuslim Life - Prayer Times, Quran, Islamic Tools</title>
                <meta name="description" content="Accurate prayer times, Quran reader, Hijri calendar, Qibla finder, and Islamic resources. Ad-free Muslim lifestyle companion." />
                <meta property="og:title" content="iMuslim Life - Prayer Times, Quran, Islamic Tools" />
                <meta property="og:description" content="Accurate prayer times, Quran reader, Hijri calendar, Qibla finder, and Islamic resources. Ad-free Muslim lifestyle companion." />
                <meta property="og:type" content="website" />
                <meta property="og:url" content="https://imuslimlife.com" /> 
                <meta property="og:image" content="https://imuslimlife.com/logo512.png" /> 
                <meta name="twitter:card" content="summary_large_image" />
                <meta name="twitter:title" content="iMuslim Life - Prayer Times, Quran, Islamic Tools" />
                <meta name="twitter:description" content="Accurate prayer times, Quran reader, Hijri calendar, Qibla finder, and Islamic resources. Ad-free Muslim lifestyle companion." />
                <meta name="twitter:image" content="https://imuslimlife.com/logo512.png" />
                {/* Add canonical link - adjust URL as needed */}
                <link rel="canonical" href={`https://imuslimlife.com${window.location.pathname}${window.location.search}`} />
                {/* Add JSON-LD Schema */}
                <script type="application/ld+json">
                    {JSON.stringify(organizationSchema)}
                </script>
                <script type="application/ld+json">
                    {JSON.stringify(websiteSchema)}
                </script>
            </Helmet>
            <AppBar component="header" position="static" sx={{
                background: 'linear-gradient(135deg, #006400, #004d00)'
            }}>
                <Container>
                    <Toolbar component="nav" disableGutters>
                        <Box 
                            component={Link} 
                            to="/" 
                            sx={{ 
                                textDecoration: 'none',
                                color: 'white',
                                flexGrow: 1,
                            }}
                        >
                            <Logo variant="default" size="medium" />
                        </Box>

                        {isMobile ? (
                            <IconButton
                                edge="end"
                                color="inherit"
                                aria-label="menu"
                                onClick={handleDrawerToggle}
                            >
                                <MenuIcon />
                            </IconButton>
                        ) : (
                            <Box component="nav" sx={{ display: 'flex' }}>
                                <Button
                                    component={Link}
                                    to="/quran"
                                    color="inherit"
                                    startIcon={
                                        <motion.div
                                            animate={{
                                                rotate: [0, 360, 360, 0],
                                                scale: [1, 1.3, 1.1, 1.4, 1],
                                                boxShadow: [
                                                    '0 0 0px #fff',
                                                    '0 0 16px #ffd700',
                                                    '0 0 32px #00e5ff',
                                                    '0 0 24px #ffd700',
                                                    '0 0 0px #fff'
                                                ],
                                                y: [0, -6, 0, 6, 0]
                                            }}
                                            transition={{
                                                duration: 2.5,
                                                repeat: Infinity,
                                                repeatType: 'loop',
                                                ease: 'easeInOut'
                                            }}
                                            style={{ display: 'inline-flex' }}
                                        >
                                            <MenuBookIcon sx={{ color: '#e4c04d', filter: 'drop-shadow(0 0 8px #e4c04d) drop-shadow(0 0 16px #e4c04d)' }} />
                                        </motion.div>
                                    }
                                    sx={{ mr: 1, fontWeight: 700 }}
                                >
                                    Quran
                                </Button>
                                <Button
                                    color="inherit"
                                    onClick={handleMenuClick}
                                    endIcon={<ArrowDropDownIcon />}
                                    sx={{ mr: 1 }}
                                >
                                    Prayer Times
                                </Button>
                                <Menu
                                    anchorEl={anchorEl}
                                    open={open}
                                    onClose={handleMenuClose}
                                    MenuListProps={{
                                        'aria-labelledby': 'prayer-times-button',
                                    }}
                                >
                                    <MenuItem 
                                        component={Link} 
                                        to="/prayer-times" 
                                        onClick={handleMenuClose}
                                        sx={{ 
                                            display: 'flex', 
                                            alignItems: 'center',
                                            color: theme.palette.text.primary
                                        }}
                                    >
                                        <AccessTimeFilledIcon fontSize="small" sx={{ mr: 1 }} />
                                        Prayer Times
                                    </MenuItem>
                                    <Divider />
                                    <MenuItem 
                                        component={Link} 
                                        to="/calendar" 
                                        onClick={handleMenuClose}
                                        sx={{ 
                                            display: 'flex', 
                                            alignItems: 'center',
                                            color: theme.palette.text.primary
                                        }}
                                    >
                                        <CalendarTodayIcon fontSize="small" sx={{ mr: 1 }} />
                                        Calendar
                                    </MenuItem>
                                    <MenuItem 
                                        component={Link} 
                                        to="/quran" 
                                        onClick={handleMenuClose}
                                        sx={{ 
                                            display: 'flex', 
                                            alignItems: 'center',
                                            color: theme.palette.text.primary
                                        }}
                                    >
                                        <motion.div
                                            animate={{
                                                rotate: [0, 360, 360, 0],
                                                scale: [1, 1.3, 1.1, 1.4, 1],
                                                boxShadow: [
                                                    '0 0 0px #fff',
                                                    '0 0 16px #e4c04d',
                                                    '0 0 32px #e4c04d',
                                                    '0 0 24px #e4c04d',
                                                    '0 0 0px #fff'
                                                ],
                                                y: [0, -6, 0, 6, 0]
                                            }}
                                            transition={{
                                                duration: 2.5,
                                                repeat: Infinity,
                                                repeatType: 'loop',
                                                ease: 'easeInOut'
                                            }}
                                            style={{ display: 'inline-flex' }}
                                        >
                                            <MenuBookIcon fontSize="small" sx={{ mr: 1, color: '#e4c04d', filter: 'drop-shadow(0 0 8px #e4c04d) drop-shadow(0 0 16px #e4c04d)' }} />
                                        </motion.div>
                                        Quran
                                    </MenuItem>
                                    <MenuItem 
                                        component={Link} 
                                        to="/api" 
                                        onClick={handleMenuClose}
                                        sx={{ 
                                            display: 'flex', 
                                            alignItems: 'center',
                                            color: theme.palette.text.primary
                                        }}
                                    >
                                        <ApiIcon fontSize="small" sx={{ mr: 1 }} />
                                        API
                                    </MenuItem>
                                </Menu>

                                <Button
                                    component={Link}
                                    to="/mobile-app"
                                    color="inherit"
                                    sx={{ mr: 1 }}
                                >
                                    Mobile App
                                </Button>
                                
                                <Button
                                    component={Link}
                                    to="/alexa-skill"
                                    color="inherit"
                                    sx={{ mr: 1 }}
                                >
                                    Alexa Skill
                                </Button>
                            </Box>
                        )}
                    </Toolbar>
                </Container>
            </AppBar>

            {/* Mobile drawer */}
            {mobileDrawer}

            <Container component="main" sx={{ flexGrow: 1, py: 4 }}>
                {children}
            </Container>

            <Footer />
        </Box>
    );
};

export default Layout;